### 3.2 核心服务实现

#### 3.2.1 TEE Pool Manager (TEE 池管理器)

```typescript
import { Worker, Job } from 'bullmq';
import Redis from 'ioredis';
import { SGXEnclave } from './sgx-enclave';

interface TEEWorker {
    id: string;
    enclave: SGXEnclave;
    status: 'idle' | 'busy' | 'error';
    currentJob?: string;
    lastHeartbeat: number;
}

class TEEPoolManager {
    private workers: Map<string, TEEWorker> = new Map();
    private redis: Redis;
    private jobQueue: any;

    constructor() {
        this.redis = new Redis(process.env.REDIS_URL!);
        this.jobQueue = new Worker('skill-execution', this.processJob.bind(this));

        // 初始化 TEE Worker 池
        this.initWorkers();
    }

    private async initWorkers() {
        // 根据配置启动多个 TEE Worker
        const workerCount = parseInt(process.env.TEE_WORKER_COUNT || '4');

        for (let i = 0; i < workerCount; i++) {
            await this.createWorker(`worker-${i}`);
        }

        // 启动健康检查
        setInterval(() => this.healthCheck(), 30000);
    }

    private async createWorker(workerId: string): Promise<TEEWorker> {
        // 1. 创建 SGX Enclave
        const enclave = await SGXEnclave.create({
            enclavePath: './skill_enclave.signed.so',
            debug: process.env.NODE_ENV !== 'production'
        });

        // 2. 远程证明
        const attestation = await enclave.getAttestation();

        // 3. 注册 Worker
        const worker: TEEWorker = {
            id: workerId,
            enclave,
            status: 'idle',
            lastHeartbeat: Date.now()
        };

        this.workers.set(workerId, worker);

        // 4. 缓存 Enclave 测量值
        await this.redis.set(`enclave:${workerId}:mrenclave`, attestation.mrenclave);

        return worker;
    }

    private async getAvailableWorker(): Promise<TEEWorker> {
        for (const [, worker] of this.workers) {
            if (worker.status === 'idle') {
                worker.status = 'busy';
                return worker;
            }
        }
        throw new Error('No available TEE workers');
    }

    private async processJob(job: Job) {
        const { skillId, input, callerAddress } = job.data;

        // 1. 获取可用 Worker
        const worker = await this.getAvailableWorker();

        try {
            // 2. 验证权限 (链上)
            const hasPermission = await this.verifyPermission(skillId, callerAddress);
            if (!hasPermission) {
                throw new Error('Permission denied');
            }

            // 3. 获取加密的 Skill
            const encryptedSkill = await this.fetchEncryptedSkill(skillId);

            // 4. 在 TEE 中执行
            const result = await worker.enclave.executeSkill(
                encryptedSkill,
                input
            );

            // 5. 记录使用
            await this.recordUsage(skillId, callerAddress);

            // 6. 释放 Worker
            worker.status = 'idle';

            return result;
        } catch (error) {
            worker.status = 'idle';
            throw error;
        }
    }

    private async healthCheck() {
        const now = Date.now();

        for (const [workerId, worker] of this.workers) {
            // 检查心跳
            if (now - worker.lastHeartbeat > 60000) {
                console.error(`Worker ${workerId} heartbeat timeout`);
                worker.status = 'error';

                // 重启 Worker
                await this.restartWorker(workerId);
            }
        }
    }

    private async restartWorker(workerId: string) {
        const worker = this.workers.get(workerId);
        if (worker) {
            try {
                await worker.enclave.destroy();
            } catch (e) {
                // ignore
            }
        }

        await this.createWorker(workerId);
    }

    // 对外接口：提交 Skill 执行任务
    async submitExecution(
        skillId: string,
        input: any,
        callerAddress: string
    ): Promise<string> {
        const job = await this.jobQueue.add('execute', {
            skillId,
            input,
            callerAddress
        });

        return job.id;
    }

    // 对外接口：查询执行结果
    async getResult(jobId: string): Promise<any> {
        const job = await this.jobQueue.getJob(jobId);
        if (!job) throw new Error('Job not found');

        const state = await job.getState();
        if (state === 'completed') {
            return job.returnvalue;
        } else if (state === 'failed') {
            throw new Error(job.failedReason);
        } else {
            throw new Error('Job still processing');
        }
    }

    private async verifyPermission(skillId: string, address: string): Promise<boolean> {
        // 调用链上合约验证权限
        return true;  // 简化
    }

    private async fetchEncryptedSkill(skillId: string): Promise<Buffer> {
        // 从 IPFS 获取加密的 Skill
        return Buffer.from('');  // 简化
    }

    private async recordUsage(skillId: string, callerAddress: string) {
        // 链上记录使用
    }
}
```

#### 3.2.2 SkillRegistry 智能合约 (Solidity)

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/finance/PaymentSplitter.sol";

contract SkillRegistry is ERC721, ERC721URIStorage, Pausable, Ownable, PaymentSplitter {

    // Skill 结构体
    struct Skill {
        uint256 id;
        string name;
        address author;
        string mrenclave;  // Enclave 测量值
        string ipfsCid;    // 加密 Skill 的 IPFS CID
        uint256 usageFee;  // 每次使用费 (wei)
        uint256 royaltyBps; // 版税 (basis points)
        bool isActive;
        uint256 totalUses;
    }

    // 权限类型
    enum PermissionType {
        USE,        // 使用权
        DERIVE,     // 衍生权
        EXTEND      // 扩展权
    }

    // 权限记录
    struct Permission {
        address grantee;
        PermissionType ptype;
        uint256 expiresAt;  // 0 = 永久
        bool isValid;
    }

    // 状态变量
    mapping(uint256 => Skill) public skills;
    mapping(uint256 => Permission[]) public permissions;
    mapping(address => uint256[]) public authorSkills;
    uint256 public skillCounter;

    // 事件
    event SkillRegistered(
        uint256 indexed skillId,
        address indexed author,
        string name,
        string mrenclave
    );
    event PermissionGranted(
        uint256 indexed skillId,
        address indexed grantee,
        PermissionType ptype,
        uint256 expiresAt
    );
    event SkillUsed(
        uint256 indexed skillId,
        address indexed user,
        uint256 fee,
        uint256 timestamp
    );

    constructor(
        address[] memory payees,
        uint256[] memory shares
    ) ERC721("SkillNFT", "SKILL") PaymentSplitter(payees, shares) {}

    // 注册新 Skill
    function registerSkill(
        string memory name,
        string memory mrenclave,
        string memory ipfsCid,
        uint256 usageFee,
        uint256 royaltyBps,
        string memory tokenURI
    ) external whenNotPaused returns (uint256) {
        require(royaltyBps <= 10000, "Royalty too high");

        skillCounter++;
        uint256 skillId = skillCounter;

        skills[skillId] = Skill({
            id: skillId,
            name: name,
            author: msg.sender,
            mrenclave: mrenclave,
            ipfsCid: ipfsCid,
            usageFee: usageFee,
            royaltyBps: royaltyBps,
            isActive: true,
            totalUses: 0
        });

        authorSkills[msg.sender].push(skillId);

        // Mint NFT
        _safeMint(msg.sender, skillId);
        _setTokenURI(skillId, tokenURI);

        emit SkillRegistered(skillId, msg.sender, name, mrenclave);

        return skillId;
    }

    // 授权使用
    function grantPermission(
        uint256 skillId,
        address grantee,
        PermissionType ptype,
        uint256 duration  // 0 = 永久
    ) external whenNotPaused {
        require(_isAuthorized(msg.sender, skillId), "Not authorized");
        require(skills[skillId].isActive, "Skill not active");

        uint256 expiresAt = duration > 0 ? block.timestamp + duration : 0;

        permissions[skillId].push(Permission({
            grantee: grantee,
            ptype: ptype,
            expiresAt: expiresAt,
            isValid: true
        }));

        emit PermissionGranted(skillId, grantee, ptype, expiresAt);
    }

    // 验证权限
    function hasPermission(
        uint256 skillId,
        address user,
        PermissionType ptype
    ) public view returns (bool) {
        Skill memory skill = skills[skillId];

        // Skill 作者或 NFT 持有者有所有权限
        if (skill.author == user || _isAuthorized(user, skillId)) {
            return true;
        }

        // 检查显式授权
        for (uint256 i = 0; i < permissions[skillId].length; i++) {
            Permission memory perm = permissions[skillId][i];
            if (perm.grantee == user && 
                perm.ptype == ptype && 
                perm.isValid &&
                (perm.expiresAt == 0 || perm.expiresAt > block.timestamp)) {
                return true;
            }
        }

        return false;
    }

    // 使用 Skill (付费)
    function useSkill(
        uint256 skillId,
        address user
    ) external payable whenNotPaused returns (bool) {
        Skill storage skill = skills[skillId];

        require(skill.isActive, "Skill not active");
        require(hasPermission(skillId, user, PermissionType.USE), "No permission");
        require(msg.value >= skill.usageFee, "Insufficient fee");

        // 支付版税给作者
        if (skill.royaltyBps > 0) {
            uint256 royalty = (msg.value * skill.royaltyBps) / 10000;
            (bool success, ) = skill.author.call{value: royalty}("");
            require(success, "Royalty transfer failed");
        }

        skill.totalUses++;

        emit SkillUsed(skillId, user, msg.value, block.timestamp);

        return true;
    }

    // 获取 Skill 信息
    function getSkill(uint256 skillId) external view returns (Skill memory) {
        return skills[skillId];
    }

    // 获取作者的所有 Skill
    function getAuthorSkills(address author) external view returns (uint256[] memory) {
        return authorSkills[author];
    }

    // 暂停/恢复
    function pause() public onlyOwner {
        _pause();
    }

    function unpause() public onlyOwner {
        _unpause();
    }

    // 重写 ERC721 方法
    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}
