### 4.2 部署架构 (Kubernetes)

```yaml
# tee-pool.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: tee-pool
spec:
  replicas: 4
  selector:
    matchLabels:
      app: tee-worker
  template:
    metadata:
      labels:
        app: tee-worker
    spec:
      # 需要 SGX 支持的节点
      nodeSelector:
        sgx.enabled: "true"
      containers:
      - name: tee-worker
        image: skill-tee-worker:latest
        securityContext:
          # SGX 设备访问
          devices:
          - name: sgx
            path: /dev/sgx
          - name: sgx_enclave
            path: /dev/sgx_enclave
          - name: sgx_provision
            path: /dev/sgx_provision
        resources:
          limits:
            sgx.intel.com/epc: "128Mi"  # EPC 内存
        env:
        - name: SGX_DEBUG
          value: "0"
        - name: REDIS_URL
          value: redis://redis:6379
        ports:
        - containerPort: 8080
        livenessProbe:
          httpGet:
            path: /health
            port: 8080
          initialDelaySeconds: 10
          periodSeconds: 30

---
# skill-runtime-service.yaml
