### 4.3 开发环境配置

#### 4.3.1 本地 SGX 开发环境 (Docker)

```dockerfile
# Dockerfile.sgx-dev
FROM ubuntu:22.04

# 安装 SGX SDK
RUN apt-get update && apt-get install -y \
    build-essential \
    wget \
    git \
    && rm -rf /var/lib/apt/lists/*

# 安装 Intel SGX SDK
WORKDIR /opt
RUN wget https://download.01.org/intel-sgx/sgx-linux/2.22/distro/ubuntu22.04-server/sgx_linux_x64_sdk_2.22.100.3.bin \
    && chmod +x sgx_linux_x64_sdk_2.22.100.3.bin \
    && echo -e 'yes\n/opt/intel' | ./sgx_linux_x64_sdk_2.22.100.3.bin

# 安装 OpenEnclave
RUN wget https://github.com/openenclave/openenclave/releases/download/v0.19.5/openenclave_0.19.5_amd64.deb \
    && dpkg -i openenclave_0.19.5_amd64.deb || true \
    && apt-get -f install -y

# 安装 Gramine
RUN git clone https://github.com/gramineproject/gramine.git \
    && cd gramine \
    && meson setup build/ --buildtype=release -Ddirect=enabled -Dsgx=enabled \
    && ninja -C build/ \
    && ninja -C build/ install

ENV SGX_SDK=/opt/intel/sgxsdk
ENV PATH=$SGX_SDK/bin:$PATH
ENV LD_LIBRARY_PATH=$SGX_SDK/lib64:$LD_LIBRARY_PATH

WORKDIR /workspace
```

